"    _resolveStreamWithFallback: function (itemPayload, preferredServer, fallbackIndex, currentSeq) {
      var self = this;
      if (typeof currentSeq === 'undefined') currentSeq = this._loadSeq;
      if (this.state === 'IDLE' || this._destroyed || (this._loadSeq !== currentSeq)) {
        return Promise.reject(new Error('Playback cancelled: player destroyed or superseded'));
      }
      var serverToTry = preferredServer;
      if (fallbackIndex > 0) {
        var altList = CLUSTER_SERVERS.filter(function (s) { return s !== preferredServer; });
        serverToTry = altList[fallbackIndex - 1];
        if (!serverToTry) {
          return Promise.reject(new Error('All server fallbacks exhausted'));
        }
      }

      return this._fetchStreamResolution(itemPayload, serverToTry).catch(function (err) {
        if (self.state === 'IDLE' || self._destroyed || (self._loadSeq !== currentSeq)) {
          return Promise.reject(new Error('Playback cancelled: player destroyed or superseded'));
        }
        console.warn('[PlayerController] Server ' + serverToTry + ' failed:', err.message);
        if (fallbackIndex < CLUSTER_SERVERS.length - 1) {
          console.log('[PlayerController] Attempting fallback cascade index ' + (fallbackIndex + 1) + '...');
          return self._resolveStreamWithFallback(itemPayload, preferredServer, fallbackIndex + 1, currentSeq);
        }
        throw err;
      });
    },"

